import { sendEmail, APP_URL } from "@/lib/resend"
import { ClientInviteEmail } from "@/emails/client-invite"

// SYNTRA_SDLC.md §5 — 30-minute invite TTL.
const INVITE_TTL_MINUTES = 30

/**
 * Sends a SYNTRA-branded personal-account activation email. The token comes
 * from client_invites.token (generated by lib/auth/invite.ts) and is embedded
 * in the activate URL as /activate/<token>.
 *
 * Returns the send result; never throws (sendEmail swallows transport errors
 * and writes them to email_logs). Callers decide whether a failed send
 * should roll back the invite row.
 */
export function sendClientInviteEmail(args: {
  to: string
  fullName: string
  token: string
}): Promise<{ ok: boolean; id: string | null }> {
  const activateUrl = `${APP_URL}/activate/${args.token}`

  return sendEmail({
    to: args.to,
    subject: "Activate your SYNTRA account",
    template: "client-invite",
    react: ClientInviteEmail({
      fullName: args.fullName,
      activateUrl,
      expiresInMinutes: INVITE_TTL_MINUTES,
    }),
    // orgId left null — personal account, no org.
    orgId: null,
  })
}
